target.css:
:root {
  --bg-card: #1e1208;
  --bg-header: #2e1a0e;
  --bg-section: #f9f3ec;
  --bg-footer: #3b2010;
  --accent-amber: #d4813a;
  --accent-gold: #f0b429;
  --text-primary: #f5e6d3;
  --text-muted: #a07850;
  --text-mid: #6b4423;
  --bar-acidity: #e07b3a;
  --bar-body: #c0522a;
  --bar-sweetness: #f0b429;
  --tag-bg: #fff7ee;
  --tag-border: #e8c49a;
  --badge-bg: #3b2010;
  --roast-bg: #d4813a;
  --roast-text: #fff7ee;
  --btn-bg: #d4813a;
  --btn-text: #fff7ee;
  --track-bg: #4a2c14;
}

article.roaster-card {
  width: 460px;
  background-color: var(--bg-card);
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 2px solid var(--accent-amber);
}

.roaster-badge {
  background-color: var(--badge-bg);
  border-radius: 8px;
  font-size: 22px;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.header-info {
  flex: 1;
}

.roaster-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 2px 0;
}

.roaster-origin {
  font-size: 10px;
  color: var(--text-muted);
  margin: 0;
}

.roast-level {
  background-color: var(--roast-bg);
  color: var(--roast-text);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.bean-details {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background-color: var(--accent-amber);
  border-bottom: 1px solid var(--accent-amber);
}

.detail-item {
  background-color: var(--bg-card);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 6px;
  gap: 2px;
}

.detail-label {
  font-size: 9px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  font-weight: 600;
}

.detail-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.lower {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.flavor-section {
  padding: 10px 12px;
  background-color: var(--bg-section);
  flex: 1;
  border-right: 1px solid var(--accent-amber);
}

.section-title {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-mid);
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin: 0 0 6px 0;
}

.flavor-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.tag {
  background-color: var(--tag-bg);
  border: 1px solid var(--tag-border);
  color: var(--text-mid);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 7px;
  border-radius: 20px;
}

.profile-bars {
  padding: 10px 12px;
  background-color: var(--bg-card);
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.profile-bars .section-title {
  color: var(--text-muted);
  margin-bottom: 2px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.bar-label {
  font-size: 10px;
  color: var(--text-muted);
  width: 56px;
  flex-shrink: 0;
  font-weight: 500;
}

.bar-track {
  flex: 1;
  height: 7px;
  background-color: var(--track-bg);
  border-radius: 4px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 4px;
}

.bar-fill.acidity {
  width: 45%;
  background-color: var(--bar-acidity);
}

.bar-fill.body {
  width: 72%;
  background-color: var(--bar-body);
}

.bar-fill.sweetness {
  width: 60%;
  background-color: var(--bar-sweetness);
}

.card-footer {
  background-color: var(--bg-footer);
  display: flex;
  align-items: center;
  padding: 9px 14px;
  gap: 10px;
  border-top: 2px solid var(--accent-amber);
}

.bag-size {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.price {
  flex: 1;
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-gold);
}

.order-btn {
  background-color: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 7px;
  padding: 7px 16px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
